function orderTotalCents(prices) {
  let total = 0;
  for (const price of prices) {
    const parts = String(price).split(".");
    const dollars = Number(parts[0] ?? "0");
    const cents = Number((parts[1] ?? "").padEnd(2, "0").slice(0, 2));
    total += dollars * 100 + cents;
  }
  return total;
}
